// Regenerates the reaction emoji picker's data and the reaction emoji
// code-point classes from a local copy of emojibase-data (MIT, CLDR names).
//
//   npm pack emojibase-data@18.0.0 && tar xzf emojibase-data-18.0.0.tgz
//   node scripts/emoji/build-emoji-data.mjs <path to the unpacked package/>
//
// Writes (all generated, do not edit by hand):
//   src/data/emoji/base.ts             emoji list, category starts, skin-tone capable indices
//   src/data/emoji/names-<locale>.ts   names + keywords per app locale (one chunk each)
//   src/lib/reactionEmojiRanges.ts     code-point classes behind lib/reactionEmoji.ts
//                                      (and the SQL check in the reaction-emoji migration)
//
// The classes come from the Unicode tables of the Node that runs this
// (printed in the header); the emoji list is filtered to Emoji <= MAX_VERSION
// so every glyph exists on the iOS versions GolfMe supports.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { join, resolve, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const MAX_VERSION = 15.1; // Emoji 15.1 = iOS 17.4 (March 2024)
const LOCALES = { en: "en", es: "es", ja: "ja", ko: "ko", "zh-CN": "zh", "zh-TW": "zh-hant" };

const src = process.argv[2];
if (!src) {
  console.error("usage: node scripts/emoji/build-emoji-data.mjs <emojibase-data package dir>");
  process.exit(1);
}
const root = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const readJson = (p) => JSON.parse(readFileSync(join(src, p), "utf8"));
const pkg = readJson("package.json");
if (pkg.name !== "emojibase-data") throw new Error("not an emojibase-data package");

// ---------------------------------------------------------------------------
// Code-point classes
// ---------------------------------------------------------------------------
function rangesOf(test) {
  const out = [];
  let start = -1;
  for (let cp = 0; cp <= 0x110000; cp++) {
    const inside = cp < 0x110000 && !(cp >= 0xd800 && cp <= 0xdfff) && test(String.fromCodePoint(cp), cp);
    if (inside && start < 0) start = cp;
    if (!inside && start >= 0) {
      out.push([start, cp - 1]);
      start = -1;
    }
  }
  return out;
}
const isRI = (cp) => cp >= 0x1f1e6 && cp <= 0x1f1ff;
const isMod = (cp) => cp >= 0x1f3fb && cp <= 0x1f3ff;
const isKeycapBase = (cp) => (cp >= 0x30 && cp <= 0x39) || cp === 0x23 || cp === 0x2a;
const reEP = /^\p{Emoji_Presentation}$/u;
const reE = /^\p{Emoji}$/u;
const reXP = /^\p{Extended_Pictographic}$/u;
const reCn = /^\p{Cn}$/u;
const reMB = /^\p{Emoji_Modifier_Base}$/u;

// Emoji presentation by default (alone = an emoji), plus not-yet-assigned
// pictographic code points (future emoji are accepted without a migration).
const PRESENTATION = rangesOf((s, cp) => !isRI(cp) && !isMod(cp) && (reEP.test(s) || (reXP.test(s) && reCn.test(s))));
// Emoji whose default is text (©, ☺, ❤): an emoji only with U+FE0F (or a
// skin tone, or inside a ZWJ sequence). Digits, # and * only as keycaps.
const TEXT_DEFAULT = rangesOf((s, cp) => !isRI(cp) && !isMod(cp) && !isKeycapBase(cp) && reE.test(s) && !reEP.test(s));
// Modifier bases, plus the same unassigned pictographic code points (a
// future emoji may take a skin tone).
const MODIFIER_BASE = rangesOf((s) => reMB.test(s) || (reXP.test(s) && reCn.test(s)));

const hex = (n) => "0x" + n.toString(16).toUpperCase();
const fmt = (rs) => "[" + rs.map(([a, b]) => `[${hex(a)}, ${hex(b)}]`).join(", ") + "]";
const rangesTs = `// GENERATED by scripts/emoji/build-emoji-data.mjs (Unicode ${process.versions.unicode}, Node ${process.versions.node}). Do not edit.
// Code-point classes for one reaction emoji (lib/reactionEmoji.ts). The SQL
// check in supabase/migrations/20261107160000_custom_reaction_emoji.sql is
// built from these same ranges (tests/reactionEmoji.test.ts compares them).
export type CodePointRange = readonly [number, number];

// Emoji presentation by default, plus unassigned Extended_Pictographic code
// points; regional indicators and skin tones excluded.
export const PRESENTATION_RANGES: readonly CodePointRange[] = ${fmt(PRESENTATION)};

// Emoji = Yes, text presentation by default: need U+FE0F alone. Digits, #
// and * excluded (keycaps only); regional indicators and skin tones excluded.
export const TEXT_DEFAULT_RANGES: readonly CodePointRange[] = ${fmt(TEXT_DEFAULT)};

// Emoji_Modifier_Base (+ unassigned Extended_Pictographic): may take one
// skin tone (U+1F3FB..U+1F3FF).
export const MODIFIER_BASE_RANGES: readonly CodePointRange[] = ${fmt(MODIFIER_BASE)};
`;

// ---------------------------------------------------------------------------
// Picker data
// ---------------------------------------------------------------------------
const versions = new Map(readJson("en/data.json").flatMap((e) => [[e.hexcode, e.version], ...(e.skins ?? []).map((s) => [s.hexcode, s.version])]));
const groupsMeta = readJson("en/messages.json").groups.filter((g) => g.key !== "component");
const enCompact = readJson("en/compact.json");

const MODS = ["\u{1F3FB}", "\u{1F3FC}", "\u{1F3FD}", "\u{1F3FE}", "\u{1F3FF}"];
// Same rule as lib/emojiPicker.ts withSkinTone.
function withSkinTone(emoji, mod) {
  const cps = [...emoji];
  const rest = cps.slice(1);
  if (rest[0] === "\u{FE0F}") rest.shift();
  return cps[0] + mod + rest.join("");
}

const list = enCompact
  .filter((e) => typeof e.group === "number" && e.group !== 2 && (versions.get(e.hexcode) ?? 99) <= MAX_VERSION)
  .sort((a, b) => a.group - b.group || a.order - b.order);

const groupKeys = [];
const groupStarts = [];
const skinIdx = [];
let skinless = 0;
list.forEach((e, i) => {
  const key = groupsMeta.find((g) => g.order === e.group)?.key;
  if (!key) throw new Error("unknown group " + e.group);
  if (groupKeys[groupKeys.length - 1] !== key) {
    groupKeys.push(key);
    groupStarts.push(i);
  }
  if (e.skins) {
    const tones = e.skins.filter((s) => (versions.get(s.hexcode) ?? 99) <= MAX_VERSION);
    const derivable = tones.length === 5 && MODS.every((m, t) => tones[t].unicode === withSkinTone(e.unicode, m));
    if (derivable) skinIdx.push(i);
    else skinless++;
  }
});
for (const e of list) if (/\s/u.test(e.unicode)) throw new Error("whitespace in emoji");

const header = `// GENERATED by scripts/emoji/build-emoji-data.mjs from ${pkg.name} ${pkg.version} (MIT, names from Unicode CLDR). Do not edit.`;
const baseTs = `${header}
// Emoji <= ${MAX_VERSION}, fully qualified, in Unicode order; components excluded.
export const EMOJI_LIST = ${JSON.stringify(list.map((e) => e.unicode).join(" "))};
export const GROUP_KEYS = ${JSON.stringify(groupKeys)} as const;
// Index into EMOJI_LIST where each group starts.
export const GROUP_STARTS: readonly number[] = ${JSON.stringify(groupStarts)};
// Emoji that take one skin tone (inserted after the first code point).
export const SKIN_TONE_INDICES: readonly number[] = ${JSON.stringify(skinIdx)};
`;

const outDir = join(root, "src/data/emoji");
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, "base.ts"), baseTs);
writeFileSync(join(root, "src/lib/reactionEmojiRanges.ts"), rangesTs);

const clean = (s) => String(s ?? "").replace(/[\t\n]/g, " ").trim();
const cap = (s) => (s ? s[0].toLocaleUpperCase() + s.slice(1) : s);
const sizes = { base: Buffer.byteLength(baseTs) };
for (const [app, dir] of Object.entries(LOCALES)) {
  const byHex = new Map(readJson(`${dir}/compact.json`).map((e) => [e.hexcode, e]));
  const messages = readJson(`${dir}/messages.json`).groups;
  const groupNames = groupKeys.map((k) => cap(clean(messages.find((g) => g.key === k)?.message ?? k)));
  let missing = 0;
  const names = list.map((e) => {
    const loc = byHex.get(e.hexcode);
    if (!loc) missing++;
    const words = [clean(loc?.label), ...(loc?.tags ?? []).map(clean)].filter(Boolean);
    return [...new Set(words)].join("\t");
  });
  const ts = `${header}
export const GROUP_NAMES: readonly string[] = ${JSON.stringify(groupNames)};
// One line per EMOJI_LIST entry: name, then keywords, tab-separated.
export const NAMES = ${JSON.stringify(names.join("\n"))};
`;
  writeFileSync(join(outDir, `names-${app}.ts`), ts);
  sizes[app] = Buffer.byteLength(ts);
  if (missing) console.log(`${app}: ${missing} emoji without a localized name`);
}
console.log(`${list.length} emoji, ${groupKeys.length} groups, ${skinIdx.length} with skin tones (${skinless} multi-person left without), sizes`, sizes);
console.log(`classes: ${PRESENTATION.length} presentation, ${TEXT_DEFAULT.length} text-default, ${MODIFIER_BASE.length} modifier-base ranges`);
